  load().then(() => { if(bootSave){level=bootSave.level;score=bootSave.score;rosterState=spec.hero.roster?characterRosterRules.restore(spec.hero.roster,bootSave.rosterState):undefined;reset();const patrols=new Map(enemies.map(enemy=>[enemy.uid,enemy]));player=bootSave.player;enemies=bootSave.enemies.map(enemy=>{const bounds=patrols.get(enemy.uid);return bounds?{...enemy,program:bounds.program,maxHp:bounds.maxHp,programState:bounds.program?behaviorProgramRules.restore(bounds.program,{x:enemy.x,y:enemy.y,width:enemy.w,height:enemy.h},enemy.programState):undefined,patrolMin:bounds.patrolMin,patrolMax:bounds.patrolMax,x:enemyCombatRules.moveWithinPatrol(enemy.x,0,0,bounds.patrolMin,bounds.patrolMax)}:enemy});items=bootSave.items;sim=bootSave.sim;mechanismState=runtimeLevels[level].authoredMap?authoredMapRules.restoreMechanisms(runtimeLevels[level].authoredMap,bootSave.mechanismState):authoredMapRules.freshMechanisms();levelScore=bootSave.levelScore;storyState=storyEngine.restore(spec,bootSave.story);unread=bootSave.unread||[];won=Boolean(bootSave.won);if(won)document.querySelector('.overlay').classList.add('show');renderStory();playtestTraceRules.begin(traceState,{kind:'restore',levelId:spec.levels[level].id,sim,x:player.x,y:player.y,target:rosterState?.characterId});bootSave=null}else{reset();beginStory()} requestAnimationFrame(loop) })
})()

styles:
*{box-sizing:border-box}body{margin:0;background:#070b17;color:#fff;font-family:system-ui,sans-serif;display:grid;place-items:center;min-height:100vh}.shell{width:min(1200px,100vw);padding:12px}.bar{display:flex;gap:12px;align-items:center;padding:10px 14px;background:#111a31;border-radius:10px 10px 0 0}.bar b{font-size:20px}.bar span{padding:5px 10px;background:#263757;border-radius:7px}canvas{width:100%;height:auto;display:block;background:#111;image-rendering:pixelated;touch-action:none}.controls{display:flex;justify-content:space-between;gap:8px;padding:10px;background:#111a31}.controls button{font:700 16px system-ui;padding:10px 16px;border:0;border-radius:8px}.hint{opacity:.72;margin-left:auto}.overlay{position:fixed;inset:0;display:none;place-items:center;background:#050816d9;font-size:32px;font-weight:800}.overlay.show{display:grid}.bar button{margin-left:auto;font:700 14px system-ui;padding:7px 12px;border:0;border-radius:7px;cursor:pointer}.paused-label{color:#8bdcff}
.narrative-rail { position: static; background: #111d23; color: #dce5df; }
.narrative-panel { padding: 10px 20px 12px; border-top: 1px solid #c4a96b30; background: linear-gradient(110deg,#192a2b,#101c24); min-width: 0; }
.narrative-panel.is-quiet { padding-top: 8px; padding-bottom: 8px; }
.narrative-heading { display:flex; align-items:center; gap:10px; min-height:20px; }
.narrative-sigil { color:#d4b572; font-size:20px; line-height:1; }
.narrative-eyebrow { color:#cfb67e; font-size:10px; letter-spacing:.15em; flex-shrink:0; }
.narrative-chapter { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:11px; color:#8caaa7; }
.narrative-link,.narrative-dismiss { border:0; background:transparent; cursor:pointer; color:#b5c8c1; font:inherit; }
.narrative-link { margin-left:auto; font-size:11px; flex-shrink:0; padding:2px 0 2px 10px; }
.narrative-link:hover { color:#f1d999; }
.narrative-link:focus-visible,.narrative-dismiss:focus-visible { outline:1px solid #d4b572; outline-offset:3px; }
.narrative-notice { position:relative; padding:5px 26px 7px 30px; animation:narrative-arrive .35s ease-out; }
.narrative-notice p { margin:0; font-family:Georgia,'Songti SC','SimSun',serif; font-size:14px; line-height:1.65; letter-spacing:.02em; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden; overflow-wrap:anywhere; }
.narrative-dismiss { position:absolute; right:0; top:4px; padding:2px; font-size:17px; color:#7e9997; }
.narrative-reading-line { position:absolute; bottom:0; left:30px; right:26px; height:1px; background:linear-gradient(90deg,#cfb67e70,transparent); transform-origin:left; animation:narrative-time 12s linear forwards; }
.narrative-archive { max-height:230px; overflow:auto; overscroll-behavior:contain; margin-top:12px; padding-right:8px; scrollbar-width:thin; }
.narrative-archive article { display:flex; gap:15px; padding:10px 0 14px; border-top:1px solid #8caaa71f; }
.narrative-entry-number { font:italic 18px Georgia,serif; color:#cfb67e80; padding-top:2px; flex-shrink:0; }
.narrative-archive h3 { margin:0 0 6px; color:#e2cc9b; font-size:12px; font-weight:500; }
.narrative-archive p { margin:0; color:#b9cdc4; font:14px/1.8 Georgia,'Songti SC','SimSun',serif; white-space:pre-wrap; overflow-wrap:anywhere; }
.narrative-objectives { background:#0e191f; border-top:1px solid #8caaa71c; padding:0 20px; font-size:11px; color:#93aaa5; }
.narrative-objectives summary { display:flex; align-items:center; gap:12px; min-height:32px; cursor:pointer; list-style:none; }
.narrative-objectives summary::-webkit-details-marker { display:none; }
.narrative-objectives summary>span { font-size:9px; letter-spacing:.1em; color:#cfb67e; flex-shrink:0; }
.narrative-objectives summary strong { font-weight:400; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.narrative-objectives summary small { margin-left:auto; flex-shrink:0; font-size:10px; }
.narrative-task-list { max-height:150px; overflow:auto; padding:4px 0 10px; line-height:1.9; overscroll-behavior:contain; }
.narrative-task-list [data-complete=true] { color:#799483; }
.narrative-task-list .ant-btn { margin-top:5px; }
@keyframes narrative-arrive { from { opacity:0; transform:translateY(4px); } to { opacity:1; transform:translateY(0); } }
@keyframes narrative-time { to { transform:scaleX(0); } }
@media(prefers-reduced-motion:reduce) { .narrative-notice,.narrative-reading-line { animation:none; } }
@media(max-width:600px) { .narrative-panel { padding-left:12px; padding-right:12px; } .narrative-objectives { padding:0 12px; } .narrative-heading { gap:7px; } .narrative-chapter { display:none; } .narrative-notice { padding-left:0; } .narrative-reading-line { left:0; } }

.offline-story{position:relative;display:block}.offline-story footer{position:absolute;right:20px;top:36px;display:flex}.offline-story .narrative-reading-line{left:50px;right:46px;bottom:10px}.offline-story.is-reading{padding-bottom:14px}.offline-objectives{color:#93aaa5}.offline-story button{font-family:inherit}.bar{flex-wrap:wrap}

/* Readable narrative type: strong body contrast, restrained display headings. */
.narrative-eyebrow { font-size:11px; font-weight:700; color:#f1d69a; text-shadow:0 1px 1px #0009; }
.narrative-chapter { font-size:12px; font-weight:700; color:#d7e3da; }
.narrative-notice p { font-family:'Microsoft YaHei','PingFang SC',system-ui,sans-serif; font-size:15px; font-weight:700; line-height:1.55; color:#f5f0e5; text-shadow:0 1px 2px #000b; }
.narrative-archive h3 { font-family:Georgia,'Songti SC','SimSun',serif; font-size:14px; font-weight:700; letter-spacing:.06em; color:#f6dca0; text-shadow:0 1px 1px #0009; }
.narrative-archive p { font-family:'Microsoft YaHei','PingFang SC',system-ui,sans-serif; font-size:15px; font-weight:600; line-height:1.8; color:#e2ece4; text-shadow:0 1px 1px #0008; }
.narrative-objectives summary strong { font-size:12px; font-weight:600; color:#dce8e0; }
.offline-objectives summary { font-size:12px; font-weight:600; color:#dce8e0; }
.narrative-link { font-weight:600; color:#d8dfcb; }

.offline-completed-actions{display:flex;flex-wrap:wrap;justify-content:center;gap:12px;margin-top:18px}.offline-completed-actions button{padding:10px 15px;border:1px solid #acd0b9;border-radius:8px;background:#398a70;color:#fffdf3;font:inherit;cursor:pointer}
